JSON Schema (concise)
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "RAG Evaluation Record",
  "type": "object",
  "required": ["eval_id","timestamp","query","chunk_count","retrieved_chunks","missing_info","expected_answer","actual_answer","actual_vs_expected"],
  "properties": {
    "eval_id": {"type":"string"},
    "timestamp": {"type":"string","format":"date-time"},
    "retriever_id": {"type":"string"},
    "llm_id": {"type":"string"},
    "query": {"type":"string"},
    "chunk_count": {"type":"integer","minimum":0},
    "retrieved_chunks": {
      "type":"array",
      "items": {
        "type":"object",
        "required":["chunk_id","text"],
        "properties": {
          "chunk_id":{"type":"string"},
          "text":{"type":"string"},
          "source":{"type":"string"},
          "relevance_score":{"type":"number","minimum":0,"maximum":1},
          "metadata":{"type":"object"}
        }
      }
    },
    "missing_info": {"type":"boolean","description":"true if retrieved context lacks answer-critical info"},
    "expected_answer": {"type":"string"},
    "actual_answer": {"type":"string"},
    "actual_vs_expected": {
      "type":"object",
      "required":["match"],
      "properties":{
        "match":{"type":"boolean"},
        "similarity_score":{"type":"number","minimum":0,"maximum":1},
        "diff":{"type":"string"}
      }
    },
    "evaluation": {
      "type":"object",
      "properties":{
        "verdict":{"type":"string","enum":["pass","fail","partial"]},
        "failure_reason":{"type":"string"},
        "notes":{"type":"string"}
      }
    }
  }
}

Example instance
{
  "eval_id": "ev-20261102-001",
  "timestamp": "2026-11-02T12:34:56Z",
  "retriever_id": "retr-v1",
  "llm_id": "gpt-llm-1",
  "query": "What is the input of the retriever and what do I get from it?",
  "chunk_count": 2,
  "retrieved_chunks": [
    {
      "chunk_id": "c1",
      "text": "We have built a rag application. We don't have chunk. What do we give in input? We give our query in input.",
      "source": "qa_page_01",
      "relevance_score": 0.92
    },
    {
      "chunk_id": "c2",
      "text": "And what we get by retrieving? We get our retrieved context. Or you can say retrieved chunks.",
      "source": "qa_page_01",
      "relevance_score": 0.95
    }
  ],
  "missing_info": true,
  "expected_answer": "Input to retriever: query/question. Output from retriever: retrieved context / retrieved chunks (relevant passages).",
  "actual_answer": "Retriever returned contextual passages but did not produce the explicit Q→A pair answer.",
  "actual_vs_expected": {
    "match": false,
    "similarity_score": 0.45,
    "diff": "Missing explicit statement: 'Input = query; Output = retrieved chunks' (expected concise mapping)."
  },
  "evaluation": {
    "verdict": "fail",
    "failure_reason": "missing_info",
    "notes": "Retriever returned related context but omitted the explicit answer; evaluation cannot confirm correctness."
  }
}

{
  "spec_version": "1.0",
  "name": "Systematic_Repeatable_LLM_Eval",
